function applyDifficulty(keepHealthRatio=false){if(!boss)return;const d=difficulties[difficultyIndex],ratio=keepHealthRatio&&boss.maxHp>0?boss.hp/boss.maxHp:1;boss.maxHp=Math.round((boss.stats.hp+Math.max(0,save.level-1)*18)*(tournamentMode?5.0:d.hp));boss.damage=Math.round(boss.stats.dmg*(tournamentMode?1.6:1)*d.damage);boss.hp=Math.max(0,Math.min(boss.maxHp,Math.round(boss.maxHp*ratio)));if(bossDefeated)boss.hp=0;const b=$('difficultyBtn');if(b)b.textContent='DIFFICULTY: '+d.name;const chip=$('difficultyChip');if(chip)chip.textContent='DIFFICULTY · '+d.name;updateHUD();}
