let audioContext=null, masterGain=null, musicTimer=null, musicStep=0;
function unlockAudio(){
 if(!sound)return;
 try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!audioContext){audioContext=new AC();masterGain=audioContext.createGain();masterGain.gain.value=.22;masterGain.connect(audioContext.destination)}if(audioContext.state==='suspended')audioContext.resume()}catch(e){}
}
function startBattleMusic(){
 if(!sound||!audioContext||musicTimer)return;
 const notes=[110,164.81,220,164.81,130.81,196,261.63,196,98,146.83,196,146.83,116.54,174.61,233.08,174.61];
 musicStep=0;
 musicTimer=setInterval(()=>{
  if(!sound||!audioContext||audioContext.state!=='running')return;
  try{
   const now=audioContext.currentTime, n=notes[musicStep%notes.length];
   const bass=audioContext.createOscillator(), bg=audioContext.createGain();
   bass.type='triangle';bass.frequency.setValueAtTime(n,now);
   bg.gain.setValueAtTime(.0001,now);bg.gain.linearRampToValueAtTime(.055,now+.035);bg.gain.exponentialRampToValueAtTime(.0001,now+.28);
   bass.connect(bg);bg.connect(masterGain);bass.start(now);bass.stop(now+.3);
   if(musicStep%2===0){
    const bell=audioContext.createOscillator(), bellGain=audioContext.createGain();
    bell.type='sine';bell.frequency.setValueAtTime(n*2.5,now);
    bellGain.gain.setValueAtTime(.0001,now);bellGain.gain.linearRampToValueAtTime(.022,now+.02);bellGain.gain.exponentialRampToValueAtTime(.0001,now+.22);
    bell.connect(bellGain);bellGain.connect(masterGain);bell.start(now);bell.stop(now+.24);
   }
   musicStep++;
  }catch(e){}
 },320);
}
function stopBattleMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null;}}
function playUltimateSfx(hero){
 if(!sound)return;unlockAudio();if(!audioContext||!masterGain)return;
 const patterns={kai:[110,220,440,880],lyra:[660,990,1320,880],brakk:[70,95,140,210],nyx:[330,247,165,82],orin:[220,330,660,990],zeph:[880,440,990,1320],moss:[130,196,261,392]};
 const seq=patterns[hero]||patterns.kai;
 try{seq.forEach((freq,i)=>{const now=audioContext.currentTime+i*.105,osc=audioContext.createOscillator(),g=audioContext.createGain();osc.type=hero==='brakk'?'sawtooth':hero==='nyx'?'triangle':'sine';osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(Math.max(40,freq*(i===seq.length-1?1.5:.82)),now+.18);g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(.14,now+.025);g.gain.exponentialRampToValueAtTime(.0001,now+.24);osc.connect(g);g.connect(masterGain);osc.start(now);osc.stop(now+.25)});}catch(e){}
}
function playSfx(kind){
 if(!sound)return;unlockAudio();if(!audioContext||!masterGain)return;
 try{
  const now=audioContext.currentTime, osc=audioContext.createOscillator(), gain=audioContext.createGain();
  if(kind==='strike'){
   const clang=audioContext.createOscillator(), cg=audioContext.createGain();
   clang.type='square';clang.frequency.setValueAtTime(1450+Math.random()*500,now);clang.frequency.exponentialRampToValueAtTime(420,now+.095);
   cg.gain.setValueAtTime(.0001,now);cg.gain.linearRampToValueAtTime(.095,now+.006);cg.gain.exponentialRampToValueAtTime(.0001,now+.11);
   clang.connect(cg);cg.connect(masterGain);clang.start(now);clang.stop(now+.12);
  }
  const presets={strike:{wave:'sawtooth',start:260,end:95,duration:.12,volume:.24},blast:{wave:'triangle',start:190,end:620,duration:.24,volume:.25},ultimate:{wave:'sawtooth',start:95,end:880,duration:.62,volume:.3},dash:{wave:'sine',start:520,end:180,duration:.16,volume:.16},jump:{wave:'sine',start:220,end:440,duration:.12,volume:.12},charge:{wave:'sine',start:180,end:520,duration:.38,volume:.16},transform:{wave:'triangle',start:120,end:740,duration:.48,volume:.23},hit:{wave:'square',start:130,end:55,duration:.14,volume:.18},death:{wave:'sawtooth',start:260,end:45,duration:.55,volume:.22},respawn:{wave:'sine',start:330,end:880,duration:.42,volume:.2},victory:{wave:'triangle',start:330,end:990,duration:.7,volume:.22},weaponArt:{wave:'sawtooth',start:150,end:760,duration:.42,volume:.24},pickup:{wave:'sine',start:520,end:920,duration:.16,volume:.12}};
  const a=presets[kind]||presets.hit;osc.type=a.wave;osc.frequency.setValueAtTime(a.start,now);osc.frequency.exponentialRampToValueAtTime(Math.max(35,a.end),now+a.duration);gain.gain.setValueAtTime(.001,now);gain.gain.linearRampToValueAtTime(a.volume,now+.018);gain.gain.exponentialRampToValueAtTime(.001,now+a.duration);osc.connect(gain);gain.connect(masterGain);osc.start(now);osc.stop(now+a.duration+.02);
 }catch(e){}
}
