function renderSkillTree(){const el=$('skillTree');if(!el)return;el.innerHTML='';const pts=$('skillPoints');if(pts)pts.textContent='AVAILABLE SKILL POINTS · '+save.skillPoints;elementalSkills.forEach(sk=>{const rank=Number(save.skills?.[sk.key]||0),b=document.createElement('button');b.className='gear-choice skill-choice'+(rank>=3?' selected':'');b.innerHTML='<span class="gear-swatch" style="background:'+sk.color+'"></span><b>'+sk.name+'</b><small>'+sk.desc+'</small><small>RANK '+rank+'/3 · '+(rank>=3?'MAXED': 'Cost: 1 skill point')+'</small>'+(rank<3?'<em>UNLOCK NEXT RANK</em>':'<em>MASTERED</em>');b.addEventListener('click',()=>{const current=Number(save.skills?.[sk.key]||0);if(current>=3){say(sk.name+' IS MAXED');return}if(save.skillPoints<1){say('DEFEAT BOSSES OR LEVEL UP TO EARN A SKILL POINT');return}save.skillPoints--;save.skills[sk.key]=current+1;saveGame();renderSkillTree();say(sk.name+' · RANK '+(current+1)+'/3');updateHUD()});el.appendChild(b)})}
