function renderLoot(){const el=$('lootInventory');if(!el)return;el.innerHTML='';const summary=$('lootSummary');if(summary)summary.textContent='✦ '+save.shards+' SHARDS · ⚔ +'+save.gearPower*4+'% DAMAGE · 🛡 '+save.armorLevel+' ARMOR';const items=(save.loot||[]).slice(-6).reverse();if(!items.length){el.innerHTML='<p class="loot-empty">Defeat a guardian to earn your first relic.</p>'}else items.forEach(item=>{const row=document.createElement('div');row.className='loot-item';row.innerHTML='<span class="loot-gem" style="color:'+item.color+'">◆</span><div><b style="color:'+item.color+'">'+item.rarity+' · '+item.name+'</b><small>+'+item.power+' gear power · '+item.realm+'</small></div>';el.appendChild(row)});renderEquipment()}
