function applyArmorVisual(p){if(!p?.group)return;const old=p.group.userData.equipmentArmor;if(old)p.group.remove(old);const set=armorSets[save.equippedSet||0];const root=new THREE.Group();const mat=new THREE.MeshStandardMaterial({color:set.color,emissive:set.color,emissiveIntensity:.42,metalness:.72,roughness:.28});const dark=new THREE.MeshStandardMaterial({color:0x20283a,metalness:.62,roughness:.36});for(const side of [-1,1]){const shoulder=new THREE.Mesh(new THREE.SphereGeometry(.245,12,10),mat);shoulder.position.set(side*.48,1.59,-.015);shoulder.scale.set(1.15,.75,1);root.add(shoulder);const bracer=new THREE.Mesh(new THREE.BoxGeometry(.16,.3,.19),mat);bracer.position.set(side*.54,1.08,-.06);root.add(bracer)}const chest=new THREE.Mesh(new THREE.OctahedronGeometry(.22,0),mat);chest.position.set(0,1.46,-.43);chest.scale.set(1,.82,.5);root.add(chest);const belt=new THREE.Mesh(new THREE.BoxGeometry(.53,.11,.25),dark);belt.position.set(0,.88,-.02);root.add(belt);root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});p.group.add(root);p.group.userData.equipmentArmor=root}
