 const root=new THREE.Group(),steel=makeMat(0xb9d8e8,.22,.88),dark=makeMat(0x172238,.32,.7),glow=new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:2.6,metalness:.25,roughness:.2});
 const part=(geo,mat,x,y,z,rx=0,ry=0,rz=0)=>{const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;root.add(m);return m};
 part(new THREE.CylinderGeometry(.045,.065,.58,10),dark,0,0,0);
