 if(kind==='sword'){part(new THREE.BoxGeometry(.13,.82,.07),steel,0,.62,0);part(new THREE.ConeGeometry(.095,.28,5),glow,0,1.15,0);part(new THREE.BoxGeometry(.42,.09,.12),glow,0,.2,0);part(new THREE.BoxGeometry(.19,.42,.08),glow,0,.65,.015)}
 if(kind==='spear'){part(new THREE.CylinderGeometry(.035,.045,1.55,8),steel,0,.72,0);part(new THREE.ConeGeometry(.16,.55,6),glow,0,1.68,0);part(new THREE.ConeGeometry(.1,.22,6),steel,0,1.36,0)}
 if(kind==='hammer'){part(new THREE.CylinderGeometry(.05,.07,.82,10),dark,0,.38,0);part(new THREE.BoxGeometry(.72,.42,.34),steel,0,.95,0);part(new THREE.BoxGeometry(.48,.48,.38),glow,0,.95,0);part(new THREE.BoxGeometry(.78,.09,.38),glow,0,.95,0)}
 if(kind==='staff'){part(new THREE.CylinderGeometry(.04,.06,1.25,10),steel,0,.55,0);part(new THREE.OctahedronGeometry(.24,1),glow,0,1.28,0);part(new THREE.TorusGeometry(.29,.035,8,24),glow,0,1.28,0);}
