function equipWeapon(p,index,announce=true){if(!p)return; p.weaponIndex=((index%weaponTypes.length)+weaponTypes.length)%weaponTypes.length;const w=weaponTypes[p.weaponIndex];if(p.group.userData.weapon)p.group.remove(p.group.userData.weapon);p.group.userData.weapon=buildWeapon(w.kind,w.color);p.group.add(p.group.userData.weapon);const set=armorSets[save.equippedSet||0];p.speed=heroes[p.key].speed*set.speed;p.damage=heroes[p.key].damage*w.damage*set.damage*(transform>0?1.5:1);if(announce)say('EQUIPPED · '+w.name);const chip=$('weaponChip');if(chip)chip.textContent='WEAPON · '+w.name;}
function createWarrior(color,scale=1){
 const g=new THREE.Group();g.scale.setScalar(scale);
 const body=makeMat(color,.28,.38),dark=makeMat(0x10172a,.34,.58),metal=makeMat(0x9bbbd0,.24,.82),glow=new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:2.1,roughness:.22});
 const limbs={arms:[],legs:[]};
 const add=(geo,mat,x,y,z,rx=0,ry=0,rz=0)=>{const m=addMesh(g,geo,mat,x,y,z);m.rotation.set(rx,ry,rz);return m};
 // layered torso armor, waist and chest crest
 add(new THREE.CapsuleGeometry(.39,.64,6,12),dark,0,1.2,0);
 add(new THREE.CapsuleGeometry(.32,.56,6,12),body,0,1.27,-.055);
 add(new THREE.BoxGeometry(.47,.25,.18),metal,0,1.43,-.34,-.12);
 add(new THREE.ConeGeometry(.12,.3,5),glow,0,1.43,-.46,0,0,Math.PI);
 add(new THREE.SphereGeometry(.29,20,16),body,0,1.94,0);
 add(new THREE.SphereGeometry(.25,18,14),dark,0,1.97,-.12);
 // luminous visor and crown fins
 add(new THREE.BoxGeometry(.32,.065,.08),glow,0,1.98,-.345);
 add(new THREE.ConeGeometry(.12,.42,5),metal,-.18,2.2,.02,0,0,-.25);
 add(new THREE.ConeGeometry(.12,.42,5),metal,.18,2.2,.02,0,0,.25);
 // shoulders, segmented arms, gauntlets, legs and boots
 for(const side of [-1,1]){
  add(new THREE.SphereGeometry(.2,12,10),metal,side*.43,1.57,0,0,0,side*.1);
  add(new THREE.SphereGeometry(.23,12,10),body,side*.47,1.55,-.04);
  const upper=add(new THREE.CapsuleGeometry(.115,.34,5,8),body,side*.5,1.2,-.015,0,0,side*.1);
  const fist=add(new THREE.SphereGeometry(.14,12,8),metal,side*.52,.98,-.04);
  const leg=add(new THREE.CapsuleGeometry(.145,.38,5,8),dark,side*.19,.57,0,0,0,side*-.035);
  limbs.arms.push({upper,fist,side});limbs.legs.push({mesh:leg,side});
  add(new THREE.BoxGeometry(.3,.15,.43),metal,side*.2,.25,-.08);
  add(new THREE.SphereGeometry(.055,8,8),glow,side*.12,1.98,-.39);
 }
 // back-mounted energy blades and a floating aura ring
 const blade=add(new THREE.ConeGeometry(.09,.8,5),glow,.34,1.45,.28,Math.PI/2,0,-.3);
 add(new THREE.ConeGeometry(.09,.8,5),glow,-.34,1.45,.28,Math.PI/2,0,.3);
 const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.025,8,48),glow);ring.position.set(0,.13,0);ring.rotation.x=Math.PI/2;g.add(ring);
 const chest=new THREE.Mesh(new THREE.OctahedronGeometry(.13,1),glow);chest.position.set(0,1.47,-.4);g.add(chest);
 g.userData={body,glow,ring,chest,limbs,attack:0,attackKind:'strike',attackDuration:0,attackClock:0,dashClock:0,baseY:0};return g
}
function addHeroSignatureLook(g,key,color){
 const accent=new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:1.35,metalness:.38,roughness:.25});
 const armor=new THREE.MeshStandardMaterial({color:key==='nyx'?0x17142b:key==='orin'?0x8b6724:key==='brakk'?0x63312a:key==='moss'?0x315b37:0x24364a,metalness:.62,roughness:.38});
 const add=(geo,mat,x,y,z,rx=0,ry=0,rz=0)=>{const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;g.add(m);return m};
 // Silhouette pieces are deliberately different per hero, not just recolors.
 if(key==='kai'){
  // Aura warrior: broad cyan shoulder fins and a bright chest crest.
  for(const side of [-1,1]){add(new THREE.ConeGeometry(.19,.62,5),accent,side*.53,1.72,.02,0,0,side*.62);add(new THREE.BoxGeometry(.16,.38,.18),armor,side*.43,1.35,-.05,0,0,side*.18)}
  add(new THREE.OctahedronGeometry(.19,1),accent,0,1.48,-.43);
 }else if(key==='lyra'){
  // Storm mage: tall pointed hood/hat, floating shoulder orbs and back mantle.
  add(new THREE.ConeGeometry(.34,.72,7),armor,0,2.36,.02);
  add(new THREE.TorusGeometry(.27,.045,7,24),accent,0,2.05,0,Math.PI/2,0,0);
  for(const side of [-1,1]){add(new THREE.SphereGeometry(.14,12,10),accent,side*.62,1.65,.03);add(new THREE.ConeGeometry(.11,.42,5),accent,side*.38,1.37,.3,Math.PI/2,0,side*.4)}
  add(new THREE.ConeGeometry(.34,.75,5),armor,0,1.1,.34,Math.PI/2,0,Math.PI);
 }else if(key==='brakk'){
  // Titan: massive layered pauldrons, thick forearm guards and a crest of spikes.
  for(const side of [-1,1]){add(new THREE.DodecahedronGeometry(.31,1),armor,side*.57,1.63,0);add(new THREE.BoxGeometry(.24,.4,.28),accent,side*.59,1.2,-.04,0,0,side*.12);add(new THREE.ConeGeometry(.14,.4,5),accent,side*.52,1.94,.02,0,0,side*.55)}
  add(new THREE.ConeGeometry(.19,.48,5),armor,0,2.25,.04);
 }else if(key==='nyx'){
  // Void assassin: swept hood, twin back blades and a dark half-cloak.
  add(new THREE.ConeGeometry(.31,.55,6),armor,0,2.24,.05,.12,0,0);
  add(new THREE.ConeGeometry(.16,.62,5),accent,-.32,1.56,.22,Math.PI/2,0,-.5);
  add(new THREE.ConeGeometry(.16,.62,5),accent,.32,1.56,.22,Math.PI/2,0,.5);
  const cloak=add(new THREE.ConeGeometry(.42,.95,5),armor,0,1.05,.3,Math.PI,0,0);cloak.scale.set(1,.85,.45);
  for(const side of [-1,1])add(new THREE.BoxGeometry(.07,.36,.07),accent,side*.24,1.96,-.32,0,0,side*.25);
 }else if(key==='orin'){
  // Starforge knight: crown, shield-like chest plate and broad gold-edged wings.
  add(new THREE.CylinderGeometry(.28,.32,.13,8),accent,0,2.12,0);
  for(let i=0;i<5;i++)add(new THREE.ConeGeometry(.07,.28,4),accent,(i-2)*.12,2.31,0,0,0,(i-2)*-.12);
  for(const side of [-1,1]){add(new THREE.BoxGeometry(.34,.5,.12),armor,side*.53,1.57,.02,0,0,side*.28);add(new THREE.ConeGeometry(.12,.48,5),accent,side*.64,1.62,.02,0,0,side*.55)}
  add(new THREE.OctahedronGeometry(.21,1),accent,0,1.48,-.43);
 }else if(key==='zeph'){
  // Ranger: swept-back feather fins and a quiver on the back.
  for(let i=0;i<3;i++){add(new THREE.ConeGeometry(.11,.58,5),accent,-.22+i*.22,2.12-i*.08,.18,Math.PI/2,0,-.3+i*.3)}
  add(new THREE.BoxGeometry(.3,.52,.18),armor,.27,1.35,.3,-.18,0,-.18);
  for(let i=0;i<3;i++)add(new THREE.CylinderGeometry(.018,.018,.58,5),accent,.18+i*.09,1.62,.32,0,0,-.2);
  add(new THREE.TorusGeometry(.28,.045,6,20),accent,0,1.45,.28,Math.PI/2,0,0);
 }else if(key==='moss'){
  // Guardian: branching antlers, leafy mantle and root-like shoulder growths.
  for(const side of [-1,1]){add(new THREE.CylinderGeometry(.045,.075,.46,6),armor,side*.18,2.22,.02,0,0,side*-.32);add(new THREE.ConeGeometry(.12,.38,5),accent,side*.34,2.43,.02,0,0,side*.5);add(new THREE.DodecahedronGeometry(.19,0),accent,side*.57,1.64,.02)}
  for(let i=0;i<3;i++)add(new THREE.ConeGeometry(.12,.42,5),accent,(i-1)*.2,1.25,.28,Math.PI/2,0,(i-1)*.22);
  add(new THREE.DodecahedronGeometry(.2,1),accent,0,1.48,-.43);
 }
 g.userData.heroLook=key;
}
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(realms[0].sky);scene.fog=new THREE.Fog(realms[0].fog,35,115);camera=new THREE.PerspectiveCamera(58,1,.1,300);renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;clock=new THREE.Clock();scene.add(new THREE.HemisphereLight(0xc4e8ff,0x35405b,2.25));const fill=new THREE.DirectionalLight(0x75cfff,1.15);fill.position.set(22,14,-18);scene.add(fill);const rimLight=new THREE.PointLight(0x4b8dff,32,70);rimLight.position.set(0,12,-20);scene.add(rimLight);const sun=new THREE.DirectionalLight(0xfff0d5,3.4);sun.position.set(-18,35,15);sun.castShadow=true;sun.shadow.mapSize.set(1536,1536);sun.shadow.bias=-0.00015;sun.shadow.normalBias=0.025;sun.shadow.camera.left=-50;sun.shadow.camera.right=50;sun.shadow.camera.top=50;sun.shadow.camera.bottom=-50;scene.add(sun);worldGroup=new THREE.Group();scene.add(worldGroup);players.push(createPlayer('kai',0));players.push(createPlayer('brakk',1));players[1].group.visible=false;buildRealm(0);window.addEventListener('resize',resize);resize();animate()}
function buildRealm(index){realmIndex=index;ambientBits.length=0;pickups.length=0;while(worldGroup.children.length)worldGroup.remove(worldGroup.children[0]);const r=realms[index];scene.background.setHex(r.sky);scene.fog.color.setHex(r.fog);const groundMat=makeMat(r.ground,.9);addMesh(worldGroup,new THREE.CylinderGeometry(75,82,2,64),groundMat,0,-1.2,0);const platformMat=makeMat(index===2?0x49405f:index===1?0x8c5342:0x91a6a8,.75,.12);for(let i=0;i<16;i++){const a=i*2.399,rad=13+(i%5)*7,x=Math.cos(a)*rad,z=Math.sin(a)*rad;const h=1+(i%4)*.7;addMesh(worldGroup,new THREE.BoxGeometry(4+(i%3),h,4+(i%4)),platformMat,x,h/2-1,z)}const rockmat=makeMat(index===1?0x6b302a:index===2?0x282341:0x718c99,.95);for(let i=0;i<48;i++){const a=Math.random()*Math.PI*2,rad=12+Math.random()*52,x=Math.cos(a)*rad,z=Math.sin(a)*rad;const s=.5+Math.random()*2;const rock=addMesh(worldGroup,new THREE.DodecahedronGeometry(s,0),rockmat,x,-.15+s*.2,z);rock.rotation.set(Math.random(),Math.random(),Math.random());if(i%4===0){const crystal=addMesh(worldGroup,new THREE.OctahedronGeometry(.55+Math.random()*.5),new THREE.MeshStandardMaterial({color:r.accent,emissive:r.accent,emissiveIntensity:.7,metalness:.4,roughness:.25}),x,.4,z);crystal.rotation.y=Math.random()*3}}
 // stylized inlaid rune paths and tall crystal clusters add scale and color
 const runeMat=new THREE.MeshStandardMaterial({color:r.accent,emissive:r.accent,emissiveIntensity:.28,metalness:.55,roughness:.35,transparent:true,opacity:.72});
 for(let i=0;i<18;i++){const a=i*Math.PI*2/18,rad=9+(i%3)*1.2;const rune=addMesh(worldGroup,new THREE.BoxGeometry(.12,.035,1.15),runeMat,Math.cos(a)*rad,.02,Math.sin(a)*rad);rune.rotation.y=-a;}
 for(let i=0;i<13;i++){const a=i*2.4,rad=24+(i%4)*5,x=Math.cos(a)*rad,z=Math.sin(a)*rad;const height=2.5+(i%4)*1.15;const crystal=addMesh(worldGroup,new THREE.OctahedronGeometry(.7+(i%3)*.18,1),new THREE.MeshStandardMaterial({color:r.accent,emissive:r.accent,emissiveIntensity:.85,metalness:.45,roughness:.2}),x,height*.42,z);crystal.scale.y=1.7;crystal.rotation.set(.2,a,.15);const shard=addMesh(worldGroup,new THREE.ConeGeometry(.22,height*.55,5),rockmat,x+.7,height*.28,z+.3);shard.rotation.z=.12;}
 // drifting atmospheric motes
 for(let i=0;i<75;i++){const mote=addMesh(worldGroup,new THREE.SphereGeometry(.035+Math.random()*.055,6,6),new THREE.MeshBasicMaterial({color:i%3===0?r.accent:0xd8f6ff,transparent:true,opacity:.28+Math.random()*.48}), (Math.random()-.5)*90,1+Math.random()*17,(Math.random()-.5)*90);mote.userData.floatSeed=Math.random()*Math.PI*2;ambientBits.push(mote)}
 // ancient gate and portal
 const gateMat=makeMat(index===2?0x4b3178:0x536c80,.45,.4);for(const x of [-3.2,3.2])addMesh(worldGroup,new THREE.BoxGeometry(.8,5,.8),gateMat,x,1.5,-29);addMesh(worldGroup,new THREE.BoxGeometry(7,.8,.9),gateMat,0,4,-29);const portal=new THREE.Mesh(new THREE.TorusGeometry(2.2,.12,10,48),new THREE.MeshStandardMaterial({color:r.accent,emissive:r.accent,emissiveIntensity:2,metalness:.3}));portal.position.set(0,1.8,-29);worldGroup.add(portal);portal.userData.portal=true;
 // distant floating islands and spires
 for(let i=0;i<10;i++){const x=(i-5)*10,z=-45-Math.random()*35,y=10+Math.random()*15;const island=addMesh(worldGroup,new THREE.ConeGeometry(3+Math.random()*3,7,6),rockmat,x,y,z);island.rotation.z=Math.PI;const top=addMesh(worldGroup,new THREE.CylinderGeometry(2.8,3.4,.7,7),platformMat,x,y+3,z);top.castShadow=false}
 // Gatherable star shards and relic caches reward exploration in each realm.
 for(let i=0;i<9;i++){const a=i*2.399+index*.6,rad=7+(i%3)*4,x=Math.cos(a)*rad,z=Math.sin(a)*rad;const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.32,1),new THREE.MeshStandardMaterial({color:i%3===0?0xffd166:r.accent,emissive:i%3===0?0xff9d27:r.accent,emissiveIntensity:1.8,metalness:.35,roughness:.2}));gem.position.set(x,.65,z);gem.userData={pickup:true,kind:i%3===0?'relic':'shard',phase:i*.8};worldGroup.add(gem);pickups.push(gem)}
 // Realm-specific scenic structures: arches, obelisks and luminous pylons.
 const scenicMat=new THREE.MeshStandardMaterial({color:r.accent,emissive:r.accent,emissiveIntensity:.22,metalness:.5,roughness:.3});
 for(let i=0;i<7;i++){const a=i*Math.PI*2/7,rad=31+(i%2)*4,x=Math.cos(a)*rad,z=Math.sin(a)*rad;const ob=addMesh(worldGroup,new THREE.CylinderGeometry(.28,.62,3.2+(i%3)*.8,6),platformMat,x,1.1,z);ob.rotation.z=Math.sin(a)*.08;const cap=addMesh(worldGroup,new THREE.OctahedronGeometry(.42,1),scenicMat,x,3.2+(i%3)*.8,z);cap.userData.floatSeed=i*.8;ambientBits.push(cap);}
 createBoss();syncRealmUI();players.forEach((p,i)=>{if(p){p.group.position.set(i===0?-2:2,0,8);p.hp=100;p.energy=0;p.cooldown=0;p.group.visible=i===0||coop}});bossDefeated=!!save.wins[index];boss.group.visible=!bossDefeated;boss.maxHp=Math.round((boss.stats.hp+Math.max(0,save.level-1)*18)*(tournamentMode?5.0:difficulties[difficultyIndex].hp));boss.damage=Math.round(boss.stats.dmg*(tournamentMode?1.6:1)*difficulties[difficultyIndex].damage);boss.hp=boss.maxHp*(bossDefeated?0:1);boss.apocalypseShown=false;updateHUD();}
