 let mx=(right?1:0)-(left?1:0), mz=(backward?1:0)-(forward?1:0);
 const len=Math.hypot(mx,mz)||1; if(mx||mz){mx/=len;mz/=len; p.facingX=mx;p.facingZ=mz;p.face=Math.abs(mx)>.2?(mx<0?-1:1):p.face;}
