('soundBtn').addEventListener('click',()=>{sound=!sound;if(sound){unlockAudio();startBattleMusic()}else stopBattleMusic();$('soundBtn').textContent=sound?'♪ SOUND ON':'♪ SOUND OFF';if(sound)playSfx('pickup');say(sound?'SOUND ENABLED':'SOUND DISABLED')});document.querySelectorAll('[data-hero]').forEach(b=>b.addEventListener('click',()=>setHero(b.dataset.hero)));document.querySelectorAll('[data-realm]').forEach(b=>b.addEventListener('click',()=>changeRealm(+b.dataset.realm)));document.querySelectorAll('[data-act]').forEach(b=>b.addEventListener('click',()=>{const act={strike:'strike',blast:'blast',dash:'dash',ultimate:'ultimate',jump:'jump',transform:'transform',charge:'charge'}[b.dataset.act];if(b.dataset.act==='weaponArt')doWeaponArt(players[0]);else if(b.dataset.act==='switchHero')cycleHero();else if(act)doAttack(players[0],act)}));document.querySelectorAll('[data-hold]').forEach(b=>{const code=b.dataset.hold;b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(code)});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(code))) });
